// @ts-check
// Ather Board: the game's core modules, and which intents work on which. The modules come from the
// repository's .ather/board.json ("modules": [{ "key", "name", "hint" }]), else S2's default list for an
// Unreal checkout, else the intents' own Areas. Sonnet sorts intents into modules (one to three each);
// each answer is kept with the intent's fingerprint (title, area, goal) and asked again only when that
// changes, or when the list of modules does. Modules made from Areas need no model: an intent sits in its
// area. Pure: no `$`; assist.mjs makes the calls and keeps the answers.

import { MODEL, jsonOf } from './brief.mjs'

/**
 * @typedef {import('./views.mjs').BoardRecord} BoardRecord
 * @typedef {{ key: string, name: string, hint: string }} Module what the model reads: `hint` says what belongs in it
 * @typedef {{ modules: Module[], byArea: boolean }} Modules `byArea`: made from the Areas, so no model is asked
 * @typedef {Record<string, string[]>} Mapping intent key → its module keys
 * @typedef {{ list: string, entries: Record<string, { print: string, modules: string[] }> }} Kept what is kept across sessions: the module list it was asked against, and each intent's answer with its fingerprint
 */

// S2's core modules: the game's systems and the work around them, in the order the map rings them.
export const S2_MODULES = /** @type {readonly Module[]} */ ([
  { key: 'mc-locomotion', name: 'Main character locomotion', hint: 'movement, sprint, dodge, traversal, jumps, camera follow' },
  { key: 'mc-combat', name: 'Main character combat', hint: 'attacks, combos, parry, hit reactions, lock-on, damage' },
  { key: 'mc-ninetails', name: 'Nine-tail abilities', hint: 'the main character’s tails, tail skills and transformations' },
  { key: 'mc-look', name: 'Main character look', hint: 'model, materials, customization, body, animation art' },
  { key: 'enemy-locomotion', name: 'Enemy locomotion', hint: 'how enemies move, navigate and animate' },
  { key: 'enemy-ai', name: 'Enemy AI', hint: 'behaviour trees, perception, decisions, encounter logic' },
  { key: 'enemy-abilities', name: 'Enemy abilities', hint: 'enemy attacks, projectiles, skills, hitboxes' },
  { key: 'bosses', name: 'Bosses', hint: 'boss fights, phases, boss abilities' },
  { key: 'quests', name: 'Quests and encounters', hint: 'quests, encounter design, scripted events, level scripting' },
  { key: 'env-presets', name: 'Environment presets', hint: 'weather, time of day, fog, lighting and look presets' },
  { key: 'env-levels', name: 'Environment levels', hint: 'level layout, world building, HLOD, streaming, foliage' },
  { key: 'vfx', name: 'VFX', hint: 'Niagara and visual effects' },
  { key: 'cinematics', name: 'Cinematics', hint: 'cutscenes, sequences, shots' },
  { key: 'audio', name: 'Audio', hint: 'sound, music, audio tools' },
  { key: 'ui', name: 'UI', hint: 'HUD, menus, front end' },
  { key: 'performance', name: 'Performance', hint: 'optimization, profiling, memory, platform budgets' },
  { key: 'tooling', name: 'Tooling', hint: 'editor tools, validators, pipeline, automation, agent tooling' },
])

// The one module of an intent's own Area, for modules made from Areas.
/** @param {string} area */
const areaKey = area => area.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'unsorted'

/**
 * The modules of a repository: its own list from .ather/board.json (`settings`), else S2's for the Unreal
 * pack, else the Areas its intents use.
 * @param {string} packId @param {Record<string, any> | null} settings @param {readonly BoardRecord[]} records @returns {Modules}
 */
export const modulesFor = (packId, settings, records) => {
  const own = Array.isArray(settings?.modules) ? settings.modules.filter((/** @type {any} */ one) => typeof one?.key === 'string' && typeof one?.name === 'string').map((/** @type {any} */ one) => ({ key: one.key, name: one.name, hint: typeof one.hint === 'string' ? one.hint : '' })) : []
  if (own.length > 0) return { modules: own, byArea: false }
  if (packId === 'unreal') return { modules: [...S2_MODULES], byArea: false }
  return { modules: [...new Set(records.map(one => one.area))].sort().map(area => ({ key: areaKey(area), name: area, hint: '' })), byArea: true }
}

// What a module answer depends on: when the intent says something else of itself, it is asked again.
/** @param {BoardRecord} record */
export const fingerprint = record => `${record.title}|${record.area}|${record.goal}`

/** @param {readonly Module[]} modules */
export const listKey = modules => modules.map(one => one.key).join(',')

/**
 * Every intent's modules: by area when the modules are the Areas, else what was kept for it while its
 * fingerprint holds. `missing`: the intents to ask the model about.
 * @param {readonly BoardRecord[]} records @param {Modules} set @param {Kept | null} kept
 * @returns {{ mapping: Mapping, missing: BoardRecord[] }}
 */
export const mappingOf = (records, set, kept) => {
  /** @type {Mapping} */
  const mapping = {}
  /** @type {BoardRecord[]} */
  const missing = []
  const valid = kept && kept.list === listKey(set.modules) ? kept.entries : {}
  for (const record of records) {
    const entry = valid[record.key]
    if (set.byArea) mapping[record.key] = [areaKey(record.area)]
    else if (entry && entry.print === fingerprint(record)) mapping[record.key] = entry.modules
    else missing.push(record)
  }
  return { mapping, missing }
}

// How many intents one request sorts: about 60 lines of digest in, a short JSON object out.
export const BATCH = 60

/** @param {readonly BoardRecord[]} records @param {readonly Module[]} modules */
export const mappingRequest = (records, modules) => ({
  model: MODEL,
  maxTokens: 4000,
  system: 'You sort a game studio’s work items ("intents") into the game’s core modules. Pick the one to three modules each intent mainly works on, most central first. Use only the module keys given; never invent one. An intent about a tool for a module belongs to that module and to tooling.',
  prompt: `The modules (key: name, what belongs in it):\n${modules.map(one => `${one.key}: ${one.name}${one.hint ? `, ${one.hint}` : ''}`).join('\n')}\n\nThe intents (key | title | area | goal):\n${records.map(one => [one.key, one.title, one.area, one.goal].join(' | ')).join('\n')}\n\nReply with JSON only, no prose around it: {"<intent key>": ["<module key>", ...], ...} for every intent above.`,
})

/**
 * The model's sorting, checked: known intents and modules only, at most three each, once each. An
 * intent the reply leaves out stays missing, to be asked again.
 * @param {string} text @param {readonly BoardRecord[]} records @param {readonly Module[]} modules @returns {Mapping}
 */
export const parseMapping = (text, records, modules) => {
  const reply = jsonOf(text)
  if (!reply) return {}
  const known = new Set(modules.map(one => one.key))
  /** @type {Mapping} */
  const mapping = {}
  for (const record of records) {
    const value = reply[record.key]
    const picked = Array.isArray(value) ? [...new Set(value.filter(key => typeof key === 'string' && known.has(key)))].slice(0, 3) : []
    if (picked.length > 0) mapping[record.key] = picked
  }
  return mapping
}

// What is kept once the model has answered for some intents.
/** @param {Kept | null} kept @param {readonly Module[]} modules @param {readonly BoardRecord[]} records @param {Mapping} answered @returns {Kept} */
export const keep = (kept, modules, records, answered) => {
  const list = listKey(modules)
  const entries = kept && kept.list === list ? { ...kept.entries } : {}
  for (const record of records) {
    const answer = answered[record.key]
    if (answer) entries[record.key] = { print: fingerprint(record), modules: answer }
  }
  return { list, entries }
}

files.hooks/brief.mjs:
// @ts-check
// Ather Board: the model's help (D7, D9). The brief: Sonnet reads a digest of the open intents and says
// what matters, as a headline and a few suggestions that each name intents and one action. Ask: a
// question typed in the pane comes back as a short answer and a cut of the board. Every reply is checked
// against what the board read: an intent it does not know, or an action it does not have, is dropped,
// so a suggestion on the board always acts on real intents. Pure: no `$`; index.mjs makes the calls.

import { ACTION_KINDS, OWNER_ACTIONS } from './act.mjs'
import { isMine } from './ather/model.mjs'
import { NO_FILTER, PANE_VIEWS, STAGES, ageText } from './views.mjs'

/**
 * @typedef {import('./views.mjs').BoardRecord} BoardRecord
 * @typedef {import('./views.mjs').View} View
 * @typedef {import('./views.mjs').Filter} Filter
 * @typedef {import('./focus.mjs').Suggestion} Suggestion
 * @typedef {{ headline: string, suggestions: Suggestion[] }} Brief
 * @typedef {{ answer: string, view: View | '', area: string, owner: string, stage: string, keys: string[] }} Answer a cut of the board: '' leaves that part as it is; `keys`: only these intents
 */

export const MODEL = 'sonnet'
export const MAX_SUGGESTIONS = 5

// One line per open intent, what a model needs to judge it and nothing more (a digest of ~80 intents is ~6k tokens).
/** @param {readonly BoardRecord[]} records @param {string} me @param {number} now */
export const digest = (records, me, now) =>
  records
    .filter(one => one.stage !== 'done')
    .map(one =>
      [
        one.key,
        STAGES.find(stage => stage.key === one.stage)?.label ?? one.stage,
        one.area,
        `${one.owner || 'no owner'}${isMine(one, me) ? ' (me)' : ''}`,
        one.total ? `${one.done}/${one.total} met` : 'no checklist',
        `changed ${ageText(one.updatedAt, now) || '?'} ago`,
        one.flags.length ? `flags: ${one.flags.map(flag => flag.label).join(', ')}` : '',
        one.calls.length ? `decisions: ${one.calls.map(call => `${call.id} ${call.title}`).join('; ')}` : '',
        one.goal,
      ]
        .filter(Boolean)
        .join(' | '),
    )
    .join('\n')

// The views an answer may pick: the pane's, less For you (which takes no filter).
const VIEWS = PANE_VIEWS.filter(view => view !== 'foryou')

const ROLE = `You help a game studio's team cut through its list of "intents" (features, each a folder with a goal, an acceptance checklist and open decisions). The board is read-only; every action you suggest is handed to a Claude Code session that asks the person before changing anything. Be concrete and brief: name intents by their key exactly as given, never invent one. Prefer what unblocks the most work: decisions waiting, work ready to close, stale or stuck work, then hygiene.`

const ACTIONS = `Actions: ${ACTION_KINDS.join(', ')}, or show (cut the board to the intents named). ${OWNER_ACTIONS.join(', ')} are for the person's own intents (marked "(me)"); for a teammate's, use ping, about or show.`

/** @param {readonly BoardRecord[]} records @param {string} me @param {number} now */
export const briefRequest = (records, me, now) => ({
  model: MODEL,
  maxTokens: 1500,
  system: `${ROLE}\n${ACTIONS}`,
  prompt: `The person at the keyboard is ${me || 'unknown'}. The open intents, one per line (key | stage | area | owner | checklist | last change | flags | decisions | goal):\n\n${digest(records, me, now)}\n\nWrite the brief: what matters most right now, for this person first, then for the team. Reply with JSON only, no prose around it:\n{"headline": "<one sentence>", "suggestions": [{"title": "<imperative, under 12 words>", "why": "<one short sentence>", "action": "<action>", "intents": ["<key>", ...]}]}\nAt most ${MAX_SUGGESTIONS} suggestions.`,
})

/** @param {string} question @param {readonly BoardRecord[]} records @param {string} me @param {number} now */
export const askRequest = (question, records, me, now) => ({
  model: MODEL,
  maxTokens: 800,
  system: `${ROLE}\nYou answer a question about the board and pick the cut of it that shows the answer. Views: ${VIEWS.join(', ')} (items: open acceptance items; modules: the game's modules). Stages: ${STAGES.map(stage => stage.key).join(', ')}.`,
  prompt: `The person at the keyboard is ${me || 'unknown'}. The open intents, one per line (key | stage | area | owner | checklist | last change | flags | decisions | goal):\n\n${digest(records, me, now)}\n\nTheir question: ${question.trim()}\n\nReply with JSON only, no prose around it:\n{"answer": "<at most three sentences>", "view": "<a view, or empty>", "area": "<an area exactly as listed, or empty>", "owner": "<an owner exactly as listed, or empty>", "stage": "<a stage, or empty>", "intents": ["<key>", ...]}\nList intents only when the answer is a particular set of them; leave the rest empty.`,
})

// The first JSON object in a reply (a model may wrap it in a code fence); null when there is none.
/** @param {string} text @returns {Record<string, unknown> | null} */
export const jsonOf = text => {
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start < 0 || end <= start) return null
  try {
    const value = JSON.parse(text.slice(start, end + 1))
    return value && typeof value === 'object' && !Array.isArray(value) ? value : null
  } catch {
    return null
  }
}

/** @param {unknown} value @param {number} max */
const words = (value, max) => (typeof value === 'string' ? value.replace(/\s+/g, ' ').trim().slice(0, max) : '')

// The keys a reply names that the board read, in its order, once each.
/** @param {unknown} value @param {readonly BoardRecord[]} records @returns {string[]} */
const knownKeys = (value, records) => {
  const known = new Set(records.map(one => one.key))
  return Array.isArray(value) ? [...new Set(value.filter(key => typeof key === 'string' && known.has(key)))] : []
}

// What a suggestion may ask for: an action, or show.
/** @type {Suggestion['action'][]} */
const PICKS = ['show', ...ACTION_KINDS]

// A brief from the model's reply; null when the reply has no brief in it. A suggestion naming no known
// intent, or an unknown action, is dropped; an action only the owner may take, suggested for a
// teammate's intent, becomes show.
/** @param {string} text @param {readonly BoardRecord[]} records @param {string} me @returns {Brief | null} */
export const parseBrief = (text, records, me) => {
  const reply = jsonOf(text)
  if (!reply) return null
  const list = Array.isArray(reply.suggestions) ? reply.suggestions : []
  /** @type {Suggestion[]} */
  const suggestions = list.flatMap((/** @type {unknown} */ item, /** @type {number} */ index) => {
    const one = item && typeof item === 'object' ? /** @type {Record<string, unknown>} */ (item) : {}
    const keys = knownKeys(one.intents, records)
    const action = PICKS.find(kind => kind === words(one.action, 20))
    if (keys.length === 0 || !action) return []
    const isOwn = keys.every(key => records.some(record => record.key === key && isMine(record, me)))
    return [{ key: `brief-${index}`, title: words(one.title, 90) || keys.join(', '), why: words(one.why, 200), action: action !== 'show' && OWNER_ACTIONS.some(kind => kind === action) && !isOwn ? 'show' : action, keys }]
  })
  return { headline: words(reply.headline, 240), suggestions: suggestions.slice(0, MAX_SUGGESTIONS) }
}

// An answer from the model's reply; null when there is none. A view, area, owner or stage the board
// does not have is left as it is ('').
/** @param {string} text @param {readonly BoardRecord[]} records @returns {Answer | null} */
export const parseAnswer = (text, records) => {
  const reply = jsonOf(text)
  if (!reply) return null
  const answer = words(reply.answer, 600)
  const pick = (/** @type {unknown} */ value, /** @type {readonly string[]} */ allowed) => { const one = words(value, 80); return allowed.includes(one) ? one : '' }
  return {
    answer,
    view: VIEWS.find(view => view === words(reply.view, 20)) ?? '',
    area: pick(reply.area, [...new Set(records.map(one => one.area))]),
    owner: pick(reply.owner, [...new Set(records.map(one => one.owner))]),
    stage: pick(reply.stage, STAGES.map(stage => stage.key)),
    keys: knownKeys(reply.intents, records),
  }
}

// The cut of the board an answer picked: its view (the table when it names intents and no view; For you,
// which has no filters, gives way to Triage), and its filters over a clean slate.
/** @param {Answer} answer @param {View} current @returns {{ view: View, filter: Filter }} */
export const answerLook = (answer, current) => ({
  view: answer.view || (answer.keys.length > 0 ? 'table' : current === 'foryou' ? 'triage' : current),
  filter: { ...NO_FILTER, area: answer.area, owner: answer.owner, stage: answer.stage, keys: answer.keys },
})

files.hooks/focus.mjs:
// @ts-check
// Ather Board: For you (D8). What the person at the keyboard can act on, before the team's views:
// their intents grouped by what each needs from them, worst first, then the rest of their open work;
// and the suggestions the board can make without a model (the brief adds the model's, brief.mjs).
// Pure: no `$`.

import { isMine } from './ather/model.mjs'
import { nextAction } from './act.mjs'
import { moduleSections } from './map.mjs'
import { DAY_MS, WARNINGS, recordsFor, rowOf, sectionsOf, sortRecords } from './views.mjs'

/**
 * @typedef {import('./views.mjs').BoardRecord} BoardRecord
 * @typedef {import('./views.mjs').Section} Section
 * @typedef {import('./views.mjs').IntentGroup} IntentGroup
 * @typedef {import('./act.mjs').ActionKind} ActionKind
 * @typedef {{ key: string, title: string, why: string, action: ActionKind | 'show', keys: string[] }} Suggestion
 *   one thing worth doing: `action` over the intents `keys` (`show`: cut the board to them)
 */

// What each of the person's open intents needs from them, in this order; an intent sits in the first that fits.
const NEEDS = /** @type {const} */ ([
  { key: 'decide', title: 'Waiting on your decision', actions: ['decide'] },
  { key: 'close', title: 'Ready for you to close', actions: ['close'] },
  { key: 'stuck', title: 'Stuck', actions: ['reason', 'unstick'] },
  { key: 'tidy', title: 'Needs a checklist or a tidy header', actions: ['checklist', 'tidy'] },
])

/** @param {string} key @param {string} title @param {string} empty @param {readonly BoardRecord[]} list @returns {IntentGroup} */
const group = (key, title, empty, list) => ({ kind: 'intents', key, title, meta: String(list.length), empty, hide: 'owner', rows: list.map(record => rowOf(record, WARNINGS)) })

/**
 * For you as sections: a lime label over what needs the person, then their other open work.
 * `me`: their git name ('' when unknown).
 * @param {readonly BoardRecord[]} records @param {string} me @returns {Section[]}
 */
export const forYou = (records, me) => {
  if (me === '') return [{ kind: 'label', key: 'label-you', title: 'For you', meta: '', isLoud: true, groups: [group('you-none', '', 'Set git user.name in this checkout so the board knows which intents are yours. Triage shows the team’s.', [])] }]
  const mine = sortRecords(records.filter(one => one.stage !== 'done' && isMine(one, me)), 'stale')
  const needs = NEEDS.map(need => ({ need, list: mine.filter(one => need.actions.some(action => action === nextAction(one, true))) })).filter(one => one.list.length > 0)
  const placed = new Set(needs.flatMap(one => one.list.map(record => record.key)))
  const rest = sortRecords(mine.filter(one => !placed.has(one.key)), 'recent')
  const count = needs.reduce((sum, one) => sum + one.list.length, 0)
  return [
    { kind: 'label', key: 'label-you', title: 'For you', meta: String(count), isLoud: true, groups: needs.length > 0 ? needs.map(({ need, list }) => group(`you-${need.key}`, need.title, '', list)) : [group('you-none', '', mine.length > 0 ? 'Nothing of yours needs you now.' : 'You own no open intents. Triage shows the team’s.', [])] },
    ...(rest.length > 0 ? [/** @type {Section} */ ({ kind: 'label', key: 'label-yours', title: 'Your other open work', meta: String(rest.length), isLoud: false, groups: [group('yours', '', '', rest)] })] : []),
  ]
}

// The brief's suggestions, then the board's own that the brief did not already make (the same action on the same intents).
/** @param {readonly Suggestion[]} brief @param {readonly Suggestion[]} plain */
export const mergeSuggestions = (brief, plain) => {
  const said = new Set(brief.map(one => `${one.action}:${[...one.keys].sort().join(',')}`))
  return [...brief, ...plain.filter(one => !said.has(`${one.action}:${[...one.keys].sort().join(',')}`))]
}

/**
 * What the board suggests without a model, most useful first, at most four: close every ready intent of
 * yours at once, answer your oldest decision, tidy your headers, and see the teammates' intents that wait on a decision.
 * @param {readonly BoardRecord[]} records @param {string} me @param {number} now @returns {Suggestion[]}
 */
export const plainSuggestions = (records, me, now) => {
  const open = records.filter(one => one.stage !== 'done')
  const mine = open.filter(one => isMine(one, me))
  const days = (/** @type {BoardRecord} */ one) => Math.max(0, Math.floor((now - one.updatedAt) / DAY_MS))
  const ready = mine.filter(one => one.stage === 'met')
  const [oldest] = sortRecords(mine.filter(one => one.calls.length > 0), 'stale')
  const untidy = mine.filter(one => nextAction(one, true) === 'tidy')
  const waiting = open.filter(one => !isMine(one, me) && one.calls.length > 0)
  /** @type {Suggestion[]} */
  const all = [
    ...(ready.length === 0 ? [] : [{ key: 'close-ready', title: ready.length === 1 ? `Close ${ready[0]?.slug}` : `Close your ${ready.length} ready intents`, why: 'Every acceptance item is met.', action: /** @type {const} */ ('close'), keys: ready.map(one => one.key) }]),
    ...(oldest ? [{ key: 'decide-oldest', title: `Answer ${oldest.calls.length === 1 ? 'the decision' : `the ${oldest.calls.length} decisions`} on ${oldest.slug}`, why: `Waiting ${days(oldest)} ${days(oldest) === 1 ? 'day' : 'days'}; the work cannot go on until then.`, action: /** @type {const} */ ('decide'), keys: [oldest.key] }] : []),
    ...(untidy.length === 0 ? [] : [{ key: 'tidy-mine', title: untidy.length === 1 ? `Fix the header of ${untidy[0]?.slug}` : `Fix the headers of your ${untidy.length} intents`, why: 'The team’s views cannot place them as written.', action: /** @type {const} */ ('tidy'), keys: untidy.map(one => one.key) }]),
    ...(waiting.length === 0 ? [] : [{ key: 'show-waiting', title: `${waiting.length} teammates’ intents wait on a decision`, why: 'Answering, or nudging their owners, unblocks the most work.', action: /** @type {const} */ ('show'), keys: waiting.map(one => one.key) }]),
  ]
  return all.slice(0, 4)
}

/**
 * What each of the pane's views draws besides its sections: the search and the pickers (`filters`), the
 * suggestions (`brief`, For you), and where the module mapping stands (`mapping`, Modules).
 * @typedef {{ filters: boolean, brief: boolean, mapping: boolean }} Extras
 */
/** @type {Extras} */
const PLAIN = { filters: true, brief: false, mapping: false }
/** @type {Partial<Record<import('./views.mjs').View, Extras>>} */
const EXTRAS = { foryou: { filters: false, brief: true, mapping: false }, modules: { filters: true, brief: false, mapping: true } }

/**
 * What a pane view shows: the records it sees, its sections (For you's, the modules', or the shared
 * views'), and its extras. The one place the pane's views are told apart.
 * @param {readonly BoardRecord[]} records @param {import('./views.mjs').Look} look
 * @param {{ me: string, modules: readonly import('./modules.mjs').Module[], mapping: import('./modules.mjs').Mapping, now: number }} context
 */
export const paneView = (records, look, { me, modules, mapping, now }) => {
  const shown = recordsFor(records, look)
  const parts = look.view === 'foryou' ? forYou(records, me) : look.view === 'modules' ? moduleSections(shown, modules, mapping, look.sort, now) : sectionsOf(shown, look, now)
  return { shown, parts, extras: EXTRAS[look.view] ?? PLAIN }
}

