// @ts-check
// Ather Automata: which pack serves a repository, and the shape every pack has.
// The core (intents, Plan → Build → Prove → Ship, Next, away windows, issues,
// the squad) is the same everywhere; a pack says what proof, traps, held
// actions and words fit the kind of project. Pure apart from the Io it is given.
//
// Selection (D3): the repository's .ather/profile.json, then markers (*.uproject
// → unreal; package.json or pyproject.toml → web), then the core alone. Read once
// per session and root, and cached.

import { gitDirOf, isAbsolute, normalFolder } from '../workspace.mjs'
import { core } from './core.mjs'
import { unreal } from './unreal.mjs'
import { makeWebPack } from './web.mjs'

/**
 * @typedef {{ state: 'none' | 'pass' | 'fail', detail: string, at?: number, by?: string }} Rung `at`, `by`: when, and by which session (its first 8 hex), the record was written
 * @typedef {{ rungs: { rung: string, value: Rung, gates?: RungGates }[], context: string[], toasts: { text: string, timeoutMs?: number }[], bumps: string[] }} ShellReading
 * @typedef {{ ran: string[], all: string[] }} RungGates on a rung that gates declare: the gates a command ran (none: a command that is no gate), of all that declare it
 * @typedef {{ id: string, pattern: RegExp, title: string, fix: string, rule?: { file: string, text: string } }} PackTrap
 * @typedef {{ name: string, verb: string, isGlobal?: boolean }} CreateItem
 * @typedef {{ isHeld: boolean, isFree: boolean, holder: string, until: string }} EditorState
 * @typedef {{ command: string, proofs: string[], id?: string, proves?: string, passOn?: 'exit' | 'counts' }} Gate `passOn`: how its tests and ui proofs pass, on its exit code (also without the field) or on test counts
 * @typedef {{ host: string, branch: string, deployment: string, url: string, expectStatus: number }} Production
 * @typedef {{ files?: readonly string[], defaultBranch?: string }} Found what else was read of a repository where its pack is chosen: the names of the files at its root, and the default branch its clone knows
 * @typedef {{ pack: Pack, held: readonly string[], isProven: boolean, base?: string }} HeldAt what a folder's own checkout holds, when that is not the session's; `base`: the branch its team merges into, when not main
 * @typedef {{ isProven?: boolean, scripts?: Record<string, string>, base?: string, at?: (folder: string | null) => HeldAt | null }} HeldContext `base`: the branch the session's checkout merges into, when not main
 * @typedef {{
 *   id: 'unreal' | 'web' | 'core',
 *   roles: readonly string[], roleLabels: Record<string, string>, roleDescriptions: Record<string, string>,
 *   roleWords: string, roleHelp: string, roleFallback: string, roleKey: string, parseRole: (text: string) => string | null,
 *   owners: string, areas: readonly string[], normalizeArea: (text: string) => string,
 *   rungLabels: Record<string, string>, proofWords: Record<string, string>, emptyEvidence: () => Record<string, Rung>,
 *   requiredRungs: (role: string) => string[], isProven: (evidence: Record<string, Rung>, role: string) => boolean, anyProofText: string,
 *   localDir: string, debriefPath: (slug: string) => string,
 *   lockFile: string | null, parseLock: (raw: string | null, nowMinutes: number) => import('./unreal.mjs').EditorLock, lockRoles: readonly string[],
 *   lockLine?: (command: string, raw: string) => string,
 *   ownCheck: { role: string, after: string, rung: string, label: string, hint: string, proveHint: string, detail: string, reply: string } | null,
 *   traps: readonly PackTrap[],
 *   held: { labels: Record<string, string>, nouns: Record<string, string>, kinds: readonly string[], defaults: readonly string[] },
 *   heldSegment: (segment: string, held: readonly string[], context: HeldContext) => string | null,
 *   mergePolicy: 'hold' | 'with-proof', mergeRungs?: readonly string[], rungGates?: Readonly<Record<string, string[]>>,
 *   baseBranch?: string,
 *   isAssetSave: (input: string) => boolean, readShell: (command: string, text: string, ran: { isError?: boolean, deny?: string }) => ShellReading,
 *   mcpKind: (input: string) => 'write' | 'read' | 'pie' | null, binaryAssets: RegExp | null, briefPaths: RegExp,
 *   skillGroups: readonly { group: string, names: readonly string[] }[], createGroups: readonly { group: string, items: readonly CreateItem[] }[],
 *   createOrder: Record<string, readonly string[]>, createTitle: string, createMeta: (editor: EditorState) => string, createPrompt: (verb: string, name: string, editor: EditorState) => string,
 *   prompts: { brief: (role: string, slug: string) => string, prove: (role: string, slug: string) => string, ship: (role: string, slug: string) => string, shipHint: (role: string) => string, briefHint: string, tour: string, tourToast: string, ask: (question: string) => string },
 *   mandate: { flags: string, allowed: string, merge: string, away: string, pane: string },
 *   statusWhat: string, notHere: string, gates: readonly Gate[], production: Production | null, scripts?: Record<string, string>,
 *   teams?: Readonly<Record<string, string>>, names?: import('../worklist.mjs').NameRules,
 *   [key: string]: unknown
 * }} Pack
 */

/**
 * What selection reads: closures over the engine, as state.mjs's Io.
 * @typedef {{ read: (path: string) => Promise<string | null>, exists: (path: string) => Promise<boolean>, list: (path: string) => Promise<{ name: string, kind: string }[]>, sessionId: () => Promise<string> }} PackIo
 */

/** @param {string | null} text */
const json = text => {
  if (!text) return null
  try {
    const value = JSON.parse(text)
    return value && typeof value === 'object' ? value : null
  } catch {
    return null
  }
}

// The default branch a clone knows: where refs/remotes/origin/HEAD points, in the git folder its worktrees share.
// Read from the files, with no git call; '' when it cannot be told.
/** @param {PackIo} io @param {string} root */
const defaultBranchOf = async (io, root) => {
  const named = await gitDirOf(io, root)
  if (!named) return ''
  // A worktree's .git file may name its git folder from the worktree.
  const gitDir = named === `${root}/.git` || isAbsolute(named) ? named : normalFolder(`${root}/${named}`)
  const common = ((await io.read(`${gitDir}/commondir`)) ?? '').trim()
  const shared = common === '' ? gitDir : isAbsolute(common) ? common : normalFolder(`${gitDir}/${common}`)
  return /^ref:\s*refs\/remotes\/origin\/(.+)/.exec((await io.read(`${shared}/refs/remotes/origin/HEAD`)) ?? '')?.[1]?.trim() ?? ''
}

/**
 * Which pack a repository gets, and why, with the default branch its clone knows ('' when it cannot be told).
 * Pure over what it reads.
 * @param {PackIo} io @param {string} root
 * @returns {Promise<{ pack: Pack, source: 'profile' | 'marker' | 'none', profile: Record<string, any> | null, defaultBranch: string }>}
 */
export const choosePack = async (io, root) => {
  const profile = json(await io.read(`${root}/.ather/profile.json`))
  const packageJson = json(await io.read(`${root}/package.json`))
  const defaultBranch = await defaultBranchOf(io, root).catch(() => '')
  const named = typeof profile?.pack === 'string' ? profile.pack.toLowerCase() : ''
  if (named === 'unreal') return { pack: unreal, source: 'profile', profile, defaultBranch }
  if (named === 'core') return { pack: core, source: 'profile', profile, defaultBranch }
  const entries = await io.list(root).catch(() => [])
  const files = entries.filter(entry => entry.kind === 'file' && typeof entry.name === 'string').map(entry => entry.name)
  const web = () => makeWebPack(profile, packageJson, { files, defaultBranch })
  if (named === 'web') return { pack: web(), source: 'profile', profile, defaultBranch }
  if (entries.some(entry => entry.kind === 'file' && /\.uproject$/i.test(entry.name))) return { pack: unreal, source: 'marker', profile, defaultBranch }
  if (packageJson || entries.some(entry => entry.kind === 'file' && /^(package\.json|pyproject\.toml)$/i.test(entry.name))) return { pack: web(), source: 'marker', profile, defaultBranch }
  return { pack: core, source: 'none', profile, defaultBranch }
}

/** @type {Map<string, ReturnType<typeof choosePack>>} */
const chosen = new Map()

// Once per session and root: a profile edited mid-session takes effect in the next session.
/** @param {PackIo} io @param {string} root */
export const packFor = async (io, root) => {
  const key = `${await io.sessionId().catch(() => '')}|${root}`
  const hit = chosen.get(key)
  if (hit) return hit
  const read = choosePack(io, root)
  chosen.set(key, read)
  return read
}

// A repository that got its intents mid-session has a profile now: its pack is chosen again.
/** @param {Pick<PackIo, 'sessionId'>} io @param {string} root */
export const forgetPack = async (io, root) => void chosen.delete(`${await io.sessionId().catch(() => '')}|${root}`)

// Tests only: forget what was chosen.
export const forgetPacks = () => chosen.clear()

export { core, unreal, makeWebPack }

files.hooks/ather/team.mjs:
// @ts-check
// Ather Automata: the team's intents as origin/main has them (or origin/<base>, where the team
// merges into another branch), each dated by its folder's last commit there, merged with the
// folders only this checkout has (D1-D3). Pure: git
// and the files come through a Repo of closures built where `$` lives (console.mjs).
// Every git call here reads, and never the working tree or the index; the fetch writes
// only the remote-tracking ref.

import { branchNamed } from './shell.mjs'

/**
 * `isAborted`: the app took the run back before it ended (it never ran to an exit code).
 * @typedef {{ exitCode: number, stdout: string, stderr?: string, isAborted?: boolean }} Ran
 * @typedef {{
 *   git: (args: readonly string[], options?: { stdin?: string, timeoutMs?: number }) => Promise<Ran>,
 *   read: (path: string) => Promise<string | null>,
 *   list: (path: string) => Promise<readonly { name: string, kind: string }[]>,
 *   mtime: (path: string) => Promise<number>,
 *   real?: (folder: string) => Promise<string>,
 * }} Repo `git` runs in the checkout with GIT_ENV; one that could not start or ran out of time answers exit code -1, the reason in stderr.
 *   `real`: the folder a path really lands in, behind any symbolic link; without it folders are compared as given
 * @typedef {{ files: string[], at: number, firstAuthor: string, prompt: string, progress: string, findings: string }} MainFolder `at`: the folder's last commit, ms
 * @typedef {{ sha: string, folders: Map<string, MainFolder> }} MainSnapshot what origin/main held at `sha`
 * @typedef {{ key: string, dirty: Set<string>, committed: Set<string> }} LocalState which folders are uncommitted, and which this branch committed since main, as of `key`
 * @typedef {{ main: MainSnapshot | null, local: LocalState | null }} TeamCache what the last read learned; each part is read again only when what it depends on moved
 * @typedef {import('./model.mjs').IntentFiles} IntentFiles
 */

// Every git call Ather makes reads without taking the index lock, and never asks for a password (D2).
export const GIT_ENV = { GIT_OPTIONAL_LOCKS: '0', GIT_TERMINAL_PROMPT: '0' }
// The remote-tracking ref of the branch a checkout's team merges into (its base).
/** @param {string} base */
const refOf = base => `origin/${base}`
export const MAIN = refOf('main')
const INTENTS = 'docs/intent'
// The fetch (D2): origin's base into origin/<base> by an explicit refspec (a narrowed remote.origin.fetch
// would not move it otherwise), no tags, no FETCH_HEAD, no submodules, and no automatic gc or
// maintenance: a background fetch in a shared checkout must not start a repack.
/** @param {string} base */
export const fetchArgs = base => ['-c', 'gc.auto=0', '-c', 'maintenance.auto=false', 'fetch', '--no-tags', '--no-write-fetch-head', '--no-recurse-submodules', 'origin', `+refs/heads/${base}:refs/remotes/${refOf(base)}`]
export const FETCH_ARGS = fetchArgs('main')
export const FETCH_EVERY_MS = 10 * 60 * 1000
// As long as the engine lets a process run: a slow fetch is not a failed one.
export const FETCH_TIMEOUT_MS = 10 * 60 * 1000
export const EMPTY_CACHE = /** @type {TeamCache} */ ({ main: null, local: null })

// The branch a checkout's team merges into: `baseBranch` in its .ather/profile.json when it reads as a branch name, else the default
// branch its clone knows (`defaultBranch`: packs/index.mjs choosePack; '' when it cannot be told), else main.
/** @param {Record<string, any> | null} profile @param {string} defaultBranch */
export const baseOf = (profile, defaultBranch) => branchNamed(profile?.baseBranch) || branchNamed(defaultBranch) || 'main'

/** @param {string} text */
const lf = text => text.replace(/\r\n/g, '\n')

// The intent folder a repository path is in: "docs/intent/lead-vfx/prompt.md" → "lead-vfx".
/** @param {string} path */
const slugOf = path => /^docs\/intent\/([^/]+)\/./.exec(path.trim())?.[1] ?? ''

// `git ls-tree -r --name-only` under docs/intent: each folder with the names of its files.
/** @param {string} text @returns {Map<string, string[]>} */
export const parseTree = text => {
  /** @type {Map<string, string[]>} */
  const folders = new Map()
  for (const line of lf(text).split('\n')) {
    const slug = slugOf(line)
    if (!slug) continue
    folders.set(slug, [...(folders.get(slug) ?? []), line.trim().slice(`${INTENTS}/${slug}/`.length)])
  }
  return folders
}

// `git log --format=%x00%ct%x09%an --name-only` under docs/intent, newest first: each folder's
// last commit time (ms) and the author of its first commit.
/** @param {string} text @returns {Map<string, { at: number, firstAuthor: string }>} */
export const parseLog = text => {
  /** @type {Map<string, { at: number, firstAuthor: string }>} */
  const folders = new Map()
  for (const record of lf(text).split('\0').slice(1)) {
    const [head = '', ...paths] = record.split('\n')
    const [seconds = '', author = ''] = head.split('\t')
    const at = Number(seconds) * 1000
    if (!Number.isFinite(at) || at <= 0) continue
    for (const slug of new Set(paths.map(slugOf).filter(Boolean))) folders.set(slug, { at: folders.get(slug)?.at ?? at, firstAuthor: author.trim() })
  }
  return folders
}

// `git cat-file --batch` output, one entry per object asked for: its text, or null when missing.
// Sizes count bytes, so the text is walked as UTF-8.
/** @param {string} text @param {number} count @returns {(string | null)[]} */
export const parseBatch = (text, count) => {
  const bytes = new TextEncoder().encode(text)
  const decoder = new TextDecoder()
  /** @type {(string | null)[]} */
  const out = []
  let at = 0
  while (out.length < count && at < bytes.length) {
    const end = bytes.indexOf(10, at)
    if (end < 0) break
    const head = decoder.decode(bytes.subarray(at, end))
    at = end + 1
    const blob = / blob (\d+)$/.exec(head)
    if (!blob) {
      out.push(null)
      continue
    }
    const size = Number(blob[1])
    out.push(decoder.decode(bytes.subarray(at, at + size)))
    at += size + 1
  }
  while (out.length < count) out.push(null)
  return out
}

// `git status --porcelain=v1 -z` under docs/intent: the folders with uncommitted or untracked files.
/** @param {string} text */
export const parseStatus = text => new Set(text.split('\0').map(entry => slugOf(entry.replace(/^.. /, ''))).filter(Boolean))

/** @param {string} prompt */
const isCompleted = prompt => /^\s*-\s*Status:\s*completed/im.test(prompt)

// The text of each file at `sha`, in order; null for one that is missing (one `git cat-file --batch`).
/** @param {Repo} repo @param {string} sha @param {readonly string[]} paths */
export const blobs = async (repo, sha, paths) => {
  if (paths.length === 0) return []
  const ran = await repo.git(['cat-file', '--batch'], { stdin: paths.map(path => `${sha}:${path}\n`).join('') })
  return ran.exitCode === 0 ? parseBatch(ran.stdout, paths.length) : paths.map(() => null)
}

/** @param {string} a @param {string} b */
const isSamePath = (a, b) => {
  const norm = (/** @type {string} */ path) => path.trim().replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()
  return norm(a) === norm(b)
}

/** @param {Repo} repo @param {string} ref */
const shaOf = async (repo, ref) => {
  const ran = await repo.git(['rev-parse', '--verify', '--quiet', `${ref}^{commit}`])
  return ran.exitCode === 0 ? ran.stdout.trim() : ''
}

// What origin/main (origin/<base>) holds under docs/intent: every folder's files, last commit and first
// author, its prompt.md, and the progress and findings of open ones. Read again only when the ref moved:
// `previous` is returned as it is while the ref is still at its commit. null: no such ref.
/** @param {Repo} repo @param {MainSnapshot | null} previous @param {string} [base] @returns {Promise<MainSnapshot | null>} */
export const readMain = async (repo, previous, base = 'main') => {
  const sha = await shaOf(repo, refOf(base))
  if (!sha) return null
  if (previous?.sha === sha) return previous
  const [tree, log] = await Promise.all([repo.git(['ls-tree', '-r', '--name-only', sha, '--', INTENTS]), repo.git(['log', sha, '--format=%x00%ct%x09%an', '--name-only', '--', INTENTS])])
  if (tree.exitCode !== 0 || log.exitCode !== 0) return previous
  const files = parseTree(tree.stdout)
  const dates = parseLog(log.stdout)
  const slugs = [...files.keys()].filter(slug => files.get(slug)?.includes('prompt.md'))
  const prompts = await blobs(repo, sha, slugs.map(slug => `${INTENTS}/${slug}/prompt.md`))
  const open = slugs.filter((_, index) => !isCompleted(prompts[index] ?? ''))
  const more = await blobs(repo, sha, open.flatMap(slug => [`${INTENTS}/${slug}/progress.md`, `${INTENTS}/${slug}/findings.md`]))
  /** @type {Map<string, MainFolder>} */
  const folders = new Map()
  slugs.forEach((slug, index) => {
    const at = open.indexOf(slug)
    folders.set(slug, {
      files: files.get(slug) ?? [],
      at: dates.get(slug)?.at ?? 0,
      firstAuthor: dates.get(slug)?.firstAuthor ?? '',
      prompt: lf(prompts[index] ?? ''),
      progress: at < 0 ? '' : lf(more[at * 2] ?? ''),
      findings: at < 0 ? '' : lf(more[at * 2 + 1] ?? ''),
    })
  })
  return { sha, folders }
}

// Which local folders are uncommitted, and which this branch committed since main. Both calls load
// the whole index of a large checkout, so readTeam asks only when `key` (main, HEAD and the intent
// files' times) moved.
/** @param {Repo} repo @param {string} sha @param {string} key @returns {Promise<LocalState>} */
const readLocal = async (repo, sha, key) => {
  const [status, ahead] = await Promise.all([repo.git(['status', '--porcelain=v1', '-z', '--untracked-files=all', '--', INTENTS]), repo.git(['log', `${sha}..HEAD`, '--format=%x00%ct%x09%an', '--name-only', '--', INTENTS])])
  return { key, dirty: parseStatus(status.exitCode === 0 ? status.stdout : ''), committed: new Set(parseLog(ahead.exitCode === 0 ? ahead.stdout : '').keys()) }
}

// The checkout's copy of an intent main has too wins when it says something else and is newer:
// uncommitted, or committed on this branch since main (D1). Main's progress and findings count only
// where main kept them (for open intents).
/** @param {{ prompt: string, progress: string, findings: string }} local @param {MainFolder} onMain @param {boolean} isNewer */
export const localWins = (local, onMain, isNewer) =>
  isNewer && (local.prompt !== onMain.prompt || (onMain.progress !== '' && local.progress !== onMain.progress) || (onMain.findings !== '' && local.findings !== onMain.findings))

// The intents to show: origin/main's, and the checkout's own folders. A folder on both is read from
// main unless the checkout's copy wins (localWins); the tracked one (`pinned`) always from the
// checkout, where its session writes. Main's are dated by their last commit there, the checkout's by
// their files (D3). `isRepo` false: not a git checkout of its own, so only its folders are read, untagged.
// `base`: the branch the checkout's team merges into, when that is not main; "main" above is then origin/<base>.
/**
 * @param {Repo} repo @param {string} root
 * @param {{ cache: TeamCache, pinned: string | null, base?: string }} options
 * @returns {Promise<{ isRepo: boolean, cache: TeamCache, intents: IntentFiles[] }>}
 */
export const readTeam = async (repo, root, { cache, pinned, base = 'main' }) => {
  const top = await repo.git(['rev-parse', '--show-toplevel'])
  // Git names the checkout's real folder; the session may have reached it through a link (macOS /var, /tmp).
  const isRepo = top.exitCode === 0 && (isSamePath(top.stdout, root) || (repo.real !== undefined && isSamePath(top.stdout, await repo.real(root).catch(() => root))))
  const main = isRepo ? await readMain(repo, cache.main, base) : null
  const folders = []
  for (const entry of await repo.list(`${root}/${INTENTS}`).catch(() => [])) {
    if (entry.kind !== 'dir') continue
    const dir = `${root}/${INTENTS}/${entry.name}`
    const prompt = await repo.read(`${dir}/prompt.md`)
    if (prompt === null) continue
    const isOpen = !isCompleted(prompt)
    const [progress, findings] = await Promise.all([repo.read(`${dir}/progress.md`), repo.read(`${dir}/findings.md`)])
    const times = await Promise.all(['prompt.md', 'progress.md', 'findings.md', 'log.md'].map(name => repo.mtime(`${dir}/${name}`)))
    const text = { prompt: lf(prompt), progress: isOpen || entry.name === pinned ? lf(progress ?? '') : '', findings: isOpen ? lf(findings ?? '') : '' }
    folders.push({ slug: entry.name, dir, text, times })
  }
  const key = main ? [main.sha, await shaOf(repo, 'HEAD'), ...folders.map(one => `${one.slug}:${one.times.join(',')}`)].join('|') : ''
  const local = !main ? null : cache.local?.key === key ? cache.local : await readLocal(repo, main.sha, key)
  /** @type {Map<string, IntentFiles>} */
  const out = new Map()
  for (const [slug, folder] of main?.folders ?? []) {
    out.set(slug, { slug, prompt: folder.prompt, progress: folder.progress, findings: folder.findings, files: folder.files, hasDebrief: false, updatedAt: folder.at, source: 'main', firstAuthor: folder.firstAuthor })
  }
  for (const { slug, dir, text, times } of folders) {
    const onMain = main?.folders.get(slug)
    if (onMain && slug !== pinned && !localWins(text, onMain, Boolean(local && (local.dirty.has(slug) || local.committed.has(slug))))) continue
    const [prompt = 0, progress = 0, , log = 0] = times
    out.set(slug, {
      slug,
      ...text,
      files: slug === pinned ? (await repo.list(dir).catch(() => [])).map(one => one.name) : [],
      hasDebrief: false,
      updatedAt: Math.max(prompt, progress, log),
      source: 'local',
      firstAuthor: onMain?.firstAuthor ?? '',
    })
  }
  return { isRepo, cache: { main, local }, intents: [...out.values()] }
}

/**
 * Where the background fetch stands, for the sync line. `lock`: the git lock a failed fetch ran into.
 * `base`: the branch fetched, when the checkout's team does not merge into main.
 * @typedef {{ isRepo: boolean, hasMain: boolean, isFetching: boolean, triedAt: number, fetchedAt: number, failedAt: number, error: string, lock: string, base?: string }} Sync
 */

/** @type {Sync} */
export const NO_SYNC = { isRepo: false, hasMain: false, isFetching: false, triedAt: 0, fetchedAt: 0, failedAt: 0, error: '', lock: '' }

// A fetch may start on its own: a git checkout, none running, the last try at least ten minutes ago (or never).
/** @param {Sync} sync @param {number} now */
export const isFetchDue = (sync, now) => sync.isRepo && !sync.isFetching && (sync.triedAt === 0 || now - sync.triedAt >= FETCH_EVERY_MS)

// ↻ fetches at once, except after a fetch that ran into a git lock: that one waits for its next due time.
/** @param {Sync} sync @param {number} now */
export const canFetchNow = (sync, now) => sync.isRepo && !sync.isFetching && (!sync.lock || isFetchDue(sync, now))

// The lock a failed git call names ("refs/remotes/origin/main.lock", "index.lock"), inside .git; '' when none.
/** @param {string} text */
export const lockOf = text => {
  const path = (/([^\s'"]+\.lock)\b/.exec(text)?.[1] ?? '').replace(/\\/g, '/')
  return path.includes('/.git/') ? path.slice(path.lastIndexOf('/.git/') + 6) : path.split('/').pop() ?? ''
}

// Fetches origin's main, or the `base` given. Synced means git said so and origin/<base> resolves after it (`moved`: it moved).
// On a failure: git's last line of complaint, and the lock it ran into, if any. `isAborted`: the app took the
// run back, so nothing was tried.
/** @param {Repo} repo @param {string} [base] @returns {Promise<{ error: string, lock: string, moved: boolean, isAborted?: true }>} */
export const fetchMain = async (repo, base = 'main') => {
  const before = await shaOf(repo, refOf(base))
  const ran = await repo.git(base === 'main' ? FETCH_ARGS : fetchArgs(base), { timeoutMs: FETCH_TIMEOUT_MS })
  const after = await shaOf(repo, refOf(base))
  if (ran.exitCode === 0 && after) return { error: '', lock: '', moved: after !== before }
  const stderr = ran.stderr ?? ''
  return { error: (stderr.trim().split('\n').pop() || `git fetch exited with ${ran.exitCode}`).slice(0, 200), lock: lockOf(stderr), moved: false, ...(ran.isAborted ? { isAborted: /** @type {const} */ (true) } : {}) }
}

// One sync line for several checkouts: a failed fetch in any of them, else one running, else the least
// recently synced (never synced counts as the least). One checkout's is its own.
/** @param {readonly Sync[]} syncs @returns {Sync} */
export const syncSummary = syncs => {
  const repos = syncs.filter(one => one.isRepo)
  const failed = repos.find(one => one.failedAt > one.fetchedAt && !one.isFetching)
  return failed ?? repos.find(one => one.isFetching) ?? [...repos].sort((a, b) => a.fetchedAt - b.fetchedAt)[0] ?? syncs[0] ?? NO_SYNC
}

/** @param {number} ms */
const agoText = ms => {
  const minutes = Math.floor(Math.max(0, ms) / 60000)
  return minutes < 1 ? 'just now' : minutes < 60 ? `${minutes} min ago` : `${Math.floor(minutes / 60)} h ago`
}

// "synced 4 min ago ↻": how fresh the list is. A failed fetch says so, naming the git lock it ran
// into, and keeps the last good time.
/** @param {Sync} sync @param {number} now */
export const syncText = (sync, now) => {
  if (!sync.isRepo) return ''
  if (sync.isFetching) return 'syncing…'
  const synced = sync.fetchedAt ? `synced ${agoText(now - sync.fetchedAt)}` : ''
  if (sync.failedAt > sync.fetchedAt) return `${sync.lock ? `sync waits on ${sync.lock}` : 'sync failed'}${synced ? ` · ${synced}` : ''} ↻`
  if (synced) return `${synced} ↻`
  return sync.hasMain ? 'not synced yet ↻' : `no ${refOf(sync.base ?? 'main')} ↻`
}

// What git said when the last fetch failed, for the line under "sync failed"; a named lock says enough on its own line.
/** @param {Sync} sync */
export const syncError = sync => (sync.failedAt > sync.fetchedAt && !sync.isFetching && !sync.lock ? sync.error : '')

